const services={en:[['Bookkeeping','Keep day-to-day transactions organized, so your records stay useful and up to date.'],['Financial reporting','Understand business performance with clear financial statements and reporting.'],['Tax preparation','Get professional support preparing tax filings and organizing the records behind them.'],['VAT services','Get help with VAT records, preparation, and your business’s compliance workflow.'],['Payroll management','Bring consistency to payroll records and employee payment calculations.'],['Business consulting','Talk through cash flow, financial planning, and your next business decision.']],bn:[['বুককিপিং','প্রতিদিনের লেনদেন গোছানো রাখুন, যাতে হিসাব হালনাগাদ ও কাজে লাগে।'],['আর্থিক প্রতিবেদন','পরিষ্কার আর্থিক বিবরণী ও প্রতিবেদনের মাধ্যমে ব্যবসার অবস্থা বুঝুন।'],['কর প্রস্তুতি','কর দাখিলের প্রস্তুতি ও প্রয়োজনীয় নথি গোছাতে পেশাদার সহায়তা নিন।'],['ভ্যাট সেবা','ভ্যাটের নথি, প্রস্তুতি ও পরিপালন প্রক্রিয়ায় সহায়তা নিন।'],['বেতন ব্যবস্থাপনা','বেতনের নথি ও কর্মীদের পাওনা গণনায় নিয়ম ও ধারাবাহিকতা আনুন।'],['ব্যবসায়িক পরামর্শ','নগদ প্রবাহ, আর্থিক পরিকল্পনা ও ব্যবসার পরবর্তী সিদ্ধান্ত নিয়ে আলোচনা করুন।']]};
