const text=(en,bn)=>lang==='en'?en:bn;
function render(){document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(el=>el.innerHTML=dictionaries[lang][el.dataset.i]);$('#language').textContent=lang==='en'?'বাংলা':'English';$('#language').setAttribute('aria-label',lang==='en'?'Switch to Bangla':'Switch to English');$('.skip').textContent=text('Skip to content','মূল বিষয়বস্তুতে যান');$('#menu').setAttribute('aria-label',text('Toggle navigation','নেভিগেশন খুলুন বা বন্ধ করুন'));$('#assistant-close').setAttribute('aria-label',text('Close assistant','সহকারী বন্ধ করুন'));$('#policy-close').setAttribute('aria-label',text('Close policy','নীতি বন্ধ করুন'));$('#assistant').setAttribute('aria-label',text('FinSolve guided assistant','ফিনসলভ নির্দেশিত সহকারী'));$('.hero-art').setAttribute('aria-label',text('Illustrative financial overview','আর্থিক চিত্রের উদাহরণ'));$('#service-grid').innerHTML=services[lang].map((s,i)=>`<article class="service"><div class="service-number"><span>0${i+1}</span><span aria-hidden="true">↗</span></div><h3>${s[0]}</h3><p>${s[1]}</p><a href="#consultation" data-service="${i}">${text('Discuss this service →','এই সেবা নিয়ে কথা বলুন →')}</a></article>`).join('');const previousService=$('#service-select').value;$('#service-select').innerHTML=`<option value="unsure">${text('Help me choose','সঠিক সেবা বেছে নিতে সাহায্য করুন')}</option>`+services[lang].map((s,i)=>`<option value="${i}">${s[0]}</option>`).join('');if(previousService)$('#service-select').value=previousService;$('#steps').innerHTML=(lang==='en'?[['Tell us where you are','Share your business needs through the account check or a conversation.'],['Find the right support','Discuss the scope, priorities, and a service arrangement that fits.'],['Build a clearer routine','Move toward organized records and useful financial reporting.']]:[['আপনার প্রয়োজন জানান','হিসাব যাচাই বা আলোচনার মাধ্যমে ব্যবসার প্রয়োজন জানান।'],['উপযুক্ত সহায়তা খুঁজুন','কাজের পরিধি, অগ্রাধিকার ও উপযুক্ত সেবা নিয়ে আলোচনা করুন।'],['গোছানো অভ্যাস গড়ুন','গোছানো নথি ও কার্যকর আর্থিক প্রতিবেদনের দিকে এগিয়ে যান।']]).map((s,i)=>`<div class="step"><span>0${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p></div>`).join('');const current=assessmentAnswers||Array.from({length:5},(_,i)=>document.querySelector(`input[name=q${i}]:checked`)?.value);$('#questions').innerHTML=questions[lang].map((q,i)=>`<fieldset><legend>${i+1}. ${q}</legend><div class="radio-options">${[text('Yes','হ্যাঁ'),text('Sometimes','মাঝে মাঝে'),text('No / unsure','না / নিশ্চিত নই')].map((a,j)=>`<label><input type="radio" name="q${i}" value="${2-j}" required ${String(current[i])===String(2-j)?'checked':''}> ${a}</label>`).join('')}</div></fieldset>`).join('');$('#consult-form input[name=time]').placeholder=text('e.g. Sunday afternoon','যেমন: রবিবার বিকেল');$('#faqs').innerHTML=(lang==='en'?[['Who is FinSolve for?','FinSolve focuses on small and medium businesses in Bangladesh, with remote support available.'],['Is the Account Check really free?','Yes. The five-question self-assessment gives an instant result without asking for contact details. It is not an audit.'],['How do consultation requests work?','Complete the request form and send the prepared message through WhatsApp. FinSolve will arrange a time with you.'],['How much do services cost?','Pricing depends on the scope and complexity of your business. Ask FinSolve for a tailored proposal.'],['Can I speak in Bangla?','Yes. This site and its guided assistant offer English and Bangla. Mention your preferred language in your inquiry.']]:[['ফিনসলভ কাদের জন্য?','ফিনসলভ বাংলাদেশের ক্ষুদ্র ও মাঝারি ব্যবসাকে সহায়তা করে। দূর থেকেও সহায়তা পাওয়া যায়।'],['হিসাব যাচাই কি সত্যিই বিনামূল্যে?','হ্যাঁ। পাঁচটি প্রশ্নের স্ব-মূল্যায়নে যোগাযোগের তথ্য ছাড়াই সঙ্গে সঙ্গে ফলাফল পাবেন। এটি অডিট নয়।'],['পরামর্শের অনুরোধ কীভাবে কাজ করে?','ফর্ম পূরণ করে তৈরি বার্তাটি হোয়াটসঅ্যাপে পাঠান। ফিনসলভ আপনার সঙ্গে সময় ঠিক করবে।'],['সেবার খরচ কত?','কাজের পরিধি ও ব্যবসার জটিলতার ওপর মূল্য নির্ভর করে। আপনার জন্য প্রস্তাব পেতে ফিনসলভকে জানান।'],['বাংলায় কথা বলা যাবে?','হ্যাঁ। ওয়েবসাইট ও নির্দেশিত সহকারী ইংরেজি এবং বাংলা সমর্থন করে। অনুরোধে পছন্দের ভাষা জানান।']]).map(s=>`<details><summary>${s[0]}</summary><p>${s[1]}</p></details>`).join('');if(assessmentAnswers)showResult();renderChat();}
function showResult(){const score=assessmentAnswers.reduce((sum,a)=>sum+Number(a),0);const title=score>=8?text('A solid routine','ভালো অভ্যাস রয়েছে'):score>=5?text('Room to strengthen your routine','অভ্যাস আরও উন্নত করা যায়'):text('Start with the foundations','মূল অভ্যাসগুলো দিয়ে শুরু করুন');const gaps=assessmentAnswers.map((a,i)=>({a:Number(a),i})).filter(x=>x.a<2).sort((a,b)=>a.a-b.a);const next=gaps.length?gaps.slice(0,3).map(x=>advice[lang][x.i]):[text('Keep your monthly review routine and revisit it as your business grows.','মাসিক পর্যালোচনা চালিয়ে যান ও ব্যবসা বাড়ার সঙ্গে অভ্যাস হালনাগাদ করুন।')];assessmentSummary=`${text('Account Check','হিসাব যাচাই')}: ${score}/10 — ${title}\n${next.join('\n')}`;$('#share-result').hidden=false;$('#check-form').hidden=true;$('#check-result').hidden=false;$('#check-result').innerHTML=`<p class="eyebrow">${text('YOUR RESULT','আপনার ফলাফল')} · ${score}/10</p><h3>${title}</h3><p>${text('Based on your answers, here are your next steps:','আপনার উত্তরের ভিত্তিতে পরবর্তী করণীয়:')}</p><ol>${next.map(a=>`<li>${a}</li>`).join('')}</ol><p class="result-note">${text('Yes = 2, Sometimes = 1, No / unsure = 0. This reflects habits you reported; it does not verify your accounts.','হ্যাঁ = ২, মাঝে মাঝে = ১, না / নিশ্চিত নই = ০। এটি আপনার জানানো অভ্যাসের মূল্যায়ন, হিসাবের নির্ভুলতার যাচাই নয়।')}</p><a class="button" href="#consultation">${text('Discuss my results →','ফলাফল নিয়ে আলোচনা করুন →')}</a><button class="secondary" id="reset-check">${text('Take the check again','আবার যাচাই করুন')}</button>`;$('#reset-check').onclick=()=>{assessmentAnswers=null;assessmentSummary='';$('#share-result').hidden=true;$('#share-result input').checked=false;$('#check-form').reset();$('#check-form').hidden=false;$('#check-result').hidden=true;$('#check-form').querySelector('input').focus()};}
$('#check-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.currentTarget);assessmentAnswers=Array.from({length:5},(_,i)=>Number(data.get(`q${i}`)));showResult();$('#check-result').setAttribute('tabindex','-1');$('#check-result').focus()};
$('#consult-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const service=f.get('service');const message=[text('Hello FinSolve, I’d like to request a consultation.','হ্যালো ফিনসলভ, আমি পরামর্শের জন্য অনুরোধ করতে চাই।'),`${text('Name','নাম')}: ${f.get('name').trim()}`,`${text('Business','ব্যবসা')}: ${f.get('business').trim()}`,`${text('Service','সেবা')}: ${service==='unsure'?text('Help me choose','সঠিক সেবা বেছে নিতে সাহায্য করুন'):services[lang][Number(service)][0]}`,`${text('Preferred time (Bangladesh)','পছন্দের সময় (বাংলাদেশ)')}: ${f.get('time').trim()||text('Please suggest a time','একটি সময় জানান')}`,`${text('Message','বার্তা')}: ${f.get('message').trim()}`,f.get('include-result')==='on'?assessmentSummary:'',`${text('Language','ভাষা')}: ${lang==='en'?'English':'বাংলা'}`].filter(Boolean).join('\n\n');window.open('https://wa.me/8801712778704?text='+encodeURIComponent(message),'_blank','noopener,noreferrer')};
$('#language').onclick=()=>{lang=lang==='en'?'bn':'en';try{localStorage.setItem('finsolve-language',lang)}catch{}render()};$('#menu').onclick=()=>{const open=$('#nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open))};$('#nav').onclick=()=>{$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')};$('#service-grid').onclick=e=>{const a=e.target.closest('[data-service]');if(a)$('#service-select').value=a.dataset.service};
function renderChat(){const chat=$('#chat');chat.replaceChildren();function say(value,visitor=false){const p=document.createElement('p');p.textContent=value;if(visitor)p.className='visitor';chat.append(p)}say(text('Hi! What would help your business today?','হ্যালো! আজ আপনার ব্যবসার জন্য কী সহায়তা দরকার?'));let options=[];if(chatState==='start'){options=[['services',text('Choose a service','সেবা বেছে নিন')],['check',text('Check my accounts','আমার হিসাব যাচাই')],['pricing',text('Ask about pricing','মূল্য সম্পর্কে জানুন')],['consult',text('Talk to FinSolve','ফিনসলভের সঙ্গে কথা বলুন')]]}else if(chatState==='services'){say(text('Choose the area you’d like help with.','কোন বিষয়ে সাহায্য চান বেছে নিন।'));options=services[lang].map((s,i)=>['service-'+i,s[0]])}else if(chatState.startsWith('service-')){const i=Number(chatState.split('-')[1]);say(services[lang][i][0],true);say(services[lang][i][1]);options=[['qualify',text('Help with my business','আমার ব্যবসার জন্য সহায়তা')],['consult',text('Request a consultation','পরামর্শের অনুরোধ')]]}else if(chatState==='qualify'){say(text('What stage are your accounting records at?','আপনার হিসাবের নথি এখন কেমন অবস্থায়?'));options=[['new',text('Starting from scratch','নতুন করে শুরু')],['catchup',text('Need to catch up','বকেয়া হিসাব গোছাতে হবে')],['ongoing',text('Need ongoing support','নিয়মিত সহায়তা চাই')]]}else if(['new','catchup','ongoing'].includes(chatState)){say(text('A consultation will help define the right scope. Share your business details in the request form; you can review the message before sending it.','উপযুক্ত কাজের পরিধি ঠিক করতে আলোচনা দরকার। অনুরোধের ফর্মে ব্যবসার তথ্য দিন; পাঠানোর আগে বার্তা দেখে নিতে পারবেন।'));options=[['consult',text('Open request form','অনুরোধের ফর্ম খুলুন')],['check',text('Take the free check first','আগে বিনামূল্যে যাচাই করুন')]]}else if(chatState==='pricing'){say(text('Fees depend on scope, transaction volume, and complexity. FinSolve can prepare a tailored proposal after discussing your needs.','কাজের পরিধি, লেনদেনের পরিমাণ ও জটিলতার ওপর মূল্য নির্ভর করে। প্রয়োজন নিয়ে আলোচনা করে ফিনসলভ প্রস্তাব দিতে পারে।'));options=[['consult',text('Discuss pricing','মূল্য নিয়ে আলোচনা')]]}else if(chatState==='check'){say(text('The free check takes five questions. Your answers stay in this page unless you choose to include the results in a WhatsApp inquiry.','বিনামূল্যে যাচাইয়ে পাঁচটি প্রশ্ন রয়েছে। হোয়াটসঅ্যাপ অনুরোধে ফলাফল যুক্ত করলে তবেই তা শেয়ার হবে।'));options=[['goto-check',text('Start Account Check →','হিসাব যাচাই শুরু করুন →')]]}else{say(text('Use the consultation form to prepare a WhatsApp inquiry. A time is confirmed after FinSolve replies.','পরামর্শের ফর্ম দিয়ে হোয়াটসঅ্যাপ বার্তা তৈরি করুন। ফিনসলভ উত্তর দেওয়ার পর সময় নিশ্চিত হবে।'));options=[['goto-consult',text('Open consultation form →','পরামর্শের ফর্ম খুলুন →')]]}const box=$('#chat-options');box.replaceChildren();options.push(['start',text('Start again','আবার শুরু')]);options.forEach(([id,label])=>{const b=document.createElement('button');b.textContent=label;b.onclick=()=>{if(id.startsWith('goto-')){closeAssistant();const section=id==='goto-check'?'#check':'#consultation';document.querySelector(section).scrollIntoView();if(section==='#consultation'){$('#service-select').value=chosenService||'unsure';$('#consult-form input').focus({preventScroll:true})}return}if(id.startsWith('service-'))chosenService=id.split('-')[1];chatState=id;renderChat()};box.append(b)});chat.scrollTop=chat.scrollHeight;}
function closeAssistant(){$('#assistant').hidden=true;$('#assistant-launch').setAttribute('aria-expanded','false');$('#assistant-launch').focus({preventScroll:true})}$('#assistant-launch').onclick=()=>{const opening=$('#assistant').hidden;$('#assistant').hidden=!opening;$('#assistant-launch').setAttribute('aria-expanded',String(opening));if(opening)$('#assistant-close').focus()};$('#assistant-close').onclick=closeAssistant;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#assistant').hidden)closeAssistant()});
const policies={en:{privacy:`<h2>Privacy Policy</h2><p>This notice describes the current FinSolve website’s information flow.</p><h3>Account Check and assistant</h3><p>The Account Check is calculated in your browser. Answers and guided-assistant selections remain in the page’s memory and are cleared on reload. They are not submitted to a FinSolve database.</p><h3>Consultation inquiries</h3><p>The form prepares a WhatsApp message containing the details you enter and any completed Account Check summary. Opening WhatsApp passes this message to WhatsApp. You choose whether to send it. FinSolve receives it after you send it and uses it to respond to your inquiry and discuss services.</p><h3>Other services</h3><p>WhatsApp, Google Fonts, your email provider, and the site hosting provider handle data under their own policies. Loading fonts from Google sends a font request to Google. Hosting may process access logs and, for this private review version, sign-in information. FinSolve does not request sensitive financial documents through this form.</p><h3>Browser preferences</h3><p>Your chosen language is stored locally on your device. You can clear it through your browser’s site-data settings. No marketing analytics or advertising trackers are added by this site.</p><h3>Your requests</h3><p>To ask about information shared with FinSolve, or request correction or deletion, contact <a href="mailto:info@finsolveacc.com">info@finsolveacc.com</a>. Inquiry retention and operational handling must be confirmed by FinSolve before public launch.</p>`,terms:`<h2>Terms of Use</h2><p>The website provides general information about FinSolve Accounting’s services.</p><h3>Account Check</h3><p>Results depend on your answers and indicate accounting habits. They do not verify records, constitute an audit, or establish tax or VAT compliance. Professional advice requires a review of your circumstances.</p><h3>Consultations and services</h3><p>A consultation request is not a confirmed appointment. FinSolve confirms availability, scope, fees, and engagement terms separately. Do not send passwords, banking credentials, or sensitive financial documents through this website.</p><h3>External links</h3><p>WhatsApp and Ledgrr are external services with their own terms. Contact <a href="mailto:info@finsolveacc.com">info@finsolveacc.com</a> for questions about FinSolve services.</p>`},bn:{privacy:`<h2>গোপনীয়তা নীতি</h2><p>এই নীতিতে বর্তমান ফিনসলভ ওয়েবসাইটের তথ্য ব্যবহারের প্রক্রিয়া বর্ণনা করা হয়েছে।</p><h3>হিসাব যাচাই ও সহকারী</h3><p>হিসাব যাচাই আপনার ব্রাউজারেই গণনা করা হয়। উত্তর ও সহকারীর নির্বাচিত বিষয় পৃষ্ঠার মেমরিতে থাকে এবং রিলোড করলে মুছে যায়। এগুলো ফিনসলভের ডেটাবেসে পাঠানো হয় না।</p><h3>পরামর্শের অনুরোধ</h3><p>ফর্ম আপনার দেওয়া তথ্য ও সম্পন্ন হিসাব যাচাইয়ের সারাংশ দিয়ে হোয়াটসঅ্যাপ বার্তা তৈরি করে। হোয়াটসঅ্যাপ খুললে বার্তাটি সেখানে যায়। পাঠাবেন কি না আপনি ঠিক করবেন। পাঠানোর পর ফিনসলভ তা পায় এবং অনুরোধের উত্তর ও সেবা নিয়ে আলোচনার জন্য ব্যবহার করে।</p><h3>অন্যান্য সেবা</h3><p>হোয়াটসঅ্যাপ, গুগল ফন্টস, ইমেইল ও হোস্টিং সেবাদাতা নিজ নিজ নীতি অনুযায়ী তথ্য ব্যবহার করে। গুগল থেকে ফন্ট লোড হলে গুগলে একটি ফন্ট অনুরোধ যায়। হোস্টিং সেবাদাতা অ্যাক্সেস লগ এবং এই ব্যক্তিগত পর্যালোচনা সংস্করণে সাইন-ইন তথ্য প্রক্রিয়াকরণ করতে পারে। এই ফর্মে সংবেদনশীল আর্থিক নথি চাওয়া হয় না।</p><h3>ব্রাউজারের পছন্দ</h3><p>ভাষার পছন্দ আপনার ডিভাইসে সংরক্ষিত হয়। ব্রাউজারের সাইট-ডেটা সেটিংস থেকে মুছতে পারবেন। এই সাইটে বিপণন অ্যানালিটিক্স বা বিজ্ঞাপন ট্র্যাকার যোগ করা হয়নি।</p><h3>আপনার অনুরোধ</h3><p>শেয়ার করা তথ্য সম্পর্কে জানতে, সংশোধন বা মুছে ফেলার অনুরোধ করতে <a href="mailto:info@finsolveacc.com">info@finsolveacc.com</a>-এ যোগাযোগ করুন। জনসাধারণের জন্য চালুর আগে তথ্য সংরক্ষণের সময়সীমা ও পরিচালনা ফিনসলভকে নিশ্চিত করতে হবে।</p>`,terms:`<h2>ব্যবহারের শর্তাবলি</h2><p>ওয়েবসাইটে ফিনসলভ অ্যাকাউন্টিংয়ের সেবা সম্পর্কে সাধারণ তথ্য দেওয়া হয়েছে।</p><h3>হিসাব যাচাই</h3><p>ফলাফল আপনার উত্তরের ওপর নির্ভর করে এবং হিসাবরক্ষণের অভ্যাসের ধারণা দেয়। এটি নথি যাচাই, অডিট বা কর/ভ্যাট পরিপালনের প্রমাণ নয়। পেশাদার পরামর্শের জন্য আপনার পরিস্থিতি পর্যালোচনা দরকার।</p><h3>পরামর্শ ও সেবা</h3><p>অনুরোধ পাঠানো মানে সময় নিশ্চিত হওয়া নয়। ফিনসলভ সময়, কাজের পরিধি, মূল্য ও চুক্তির শর্ত আলাদাভাবে নিশ্চিত করবে। এই সাইটে পাসওয়ার্ড, ব্যাংক লগইন বা সংবেদনশীল আর্থিক নথি দেবেন না।</p><h3>বাইরের লিংক</h3><p>হোয়াটসঅ্যাপ ও লেডজার আলাদা সেবা এবং তাদের নিজস্ব শর্ত রয়েছে। ফিনসলভের সেবা সম্পর্কে জানতে <a href="mailto:info@finsolveacc.com">info@finsolveacc.com</a>-এ যোগাযোগ করুন।</p>`}};
document.querySelectorAll('[data-policy]').forEach(b=>b.onclick=()=>{$('#policy-content').innerHTML=policies[lang][b.dataset.policy];$('#policy').showModal()});$('#policy-close').onclick=()=>$('#policy').close();$('#policy').onclick=e=>{if(e.target===$('#policy')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};$('#year').textContent=new Date().getFullYear();render();
